//! The Rust client library of the multiplexer, a message broker: a Rust
//! program connects to multiplexers as a peer and exchanges messages with
//! the C++ and Python peers, by the protocol docs/README.md explains.
//! This crate is the library's root; its modules mirror the C++ library's
//! files, each naming the file it mirrors.
//!
//! The protocol's messages are prost's inside the crate, generated by
//! rust/codegen and committed; the system's message and peer types are in
//! [`constants`], generated by `mxcontrol generate_constants --rust` from
//! multiplexer.rules, and the timeouts and limits of multiplexer/defaults.h
//! are at the crate's root.

#![deny(unsafe_code)]
#![deny(missing_docs)]

/// The message and peer types of the system rules, multiplexer.rules, the
/// ones every rules file starts with: `types::PING`, `types::DELIVERY_ERROR`
/// and the others the protocol itself uses. A program's own rules file
/// generates a module of the same shape with its own types beside these.
/// Generated: a constant's name, the rules file's, is its documentation.
#[allow(missing_docs)]
pub mod constants;
mod core;
mod defaults;
mod driver;
mod endpoint;
mod engine;
mod error;
mod fork;
mod frame;
mod handles;
mod ids;
mod inbox;
mod log_summary;
mod message;
mod pending;
mod proto;
mod servers;
mod spanset;
mod sync_client;
#[cfg(test)]
mod test_log;
mod threaded_client;
mod xxh3;

